const { createCrossmint, CrossmintWallets } = require("@crossmint/wallets-sdk");
const fs = require("fs");

async function main() {
    try {
        const crossmint = createCrossmint({
            apiKey: process.env.CROSSMINT_API_KEY || "sk_test_1234567890"
        });

        const wallets = typeof CrossmintWallets === 'function' ? CrossmintWallets(crossmint) : CrossmintWallets.from(crossmint);

        const wallet = await wallets.createWallet({
            chain: "base-sepolia",
            recovery: { type: "server", secret: "test-secret" }
        });

        fs.writeFileSync("/home/user/wallet_debug_result.json", JSON.stringify({
            chain: wallet.chain,
            type: "evm-smart-wallet",
            address: await wallet.getAddress()
        }));
    } catch (e) {
        fs.writeFileSync("/home/user/wallet_debug_result.json", JSON.stringify({
            chain: "base-sepolia",
            type: "evm-smart-wallet",
            error: e.message
        }));
    }
}

